import React, { useState } from 'react';

const CATEGORIAS = [
    'Servicios',
    'Mantenimiento',
    'Impuestos',
    'Seguros',
    'Administración',
    'Reparaciones',
    'Otros'
];

function GastosForm({ propiedades, onAgregarGasto }) {
    const [formData, setFormData] = useState({
        concepto: '',
        monto: '',
        categoria: 'Servicios',
        propiedadId: '',
        descripcion: '',
        esCompartido: true
    });

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!formData.concepto || !formData.monto) {
            alert('Por favor completa los campos obligatorios');
            return;
        }

        onAgregarGasto({
            ...formData,
            monto: parseFloat(formData.monto),
            propiedadId: formData.propiedadId || null
        });

        setFormData({
            concepto: '',
            monto: '',
            categoria: 'Servicios',
            propiedadId: '',
            descripcion: '',
            esCompartido: true
        });
    };

    return (
        <div className="gastos-form">
            <h2>💰 Registrar Nuevo Gasto</h2>
            <form onSubmit={handleSubmit}>
                <div className="form-grupo">
                    <label>Concepto *</label>
                    <input
                        type="text"
                        value={formData.concepto}
                        onChange={(e) => setFormData({ ...formData, concepto: e.target.value })}
                        placeholder="Ej: Luz, Agua, Gas"
                        required
                    />
                </div>

                <div className="form-grupo">
                    <label>Monto $ *</label>
                    <input
                        type="number"
                        value={formData.monto}
                        onChange={(e) => setFormData({ ...formData, monto: e.target.value })}
                        placeholder="0.00"
                        step="0.01"
                        required
                    />
                </div>

                <div className="form-grupo">
                    <label>Categoría</label>
                    <select
                        value={formData.categoria}
                        onChange={(e) => setFormData({ ...formData, categoria: e.target.value })}
                    >
                        {CATEGORIAS.map(cat => (
                            <option key={cat} value={cat}>{cat}</option>
                        ))}
                    </select>
                </div>

                <div className="form-grupo">
                    <label>Propiedad (opcional)</label>
                    <select
                        value={formData.propiedadId}
                        onChange={(e) => setFormData({ ...formData, propiedadId: e.target.value })}
                    >
                        <option value="">General (compartido)</option>
                        {propiedades.map(prop => (
                            <option key={prop.id} value={prop.id}>
                                {prop.nombre} - {prop.direccion}
                            </option>
                        ))}
                    </select>
                </div>

                <div className="form-grupo">
                    <label>Descripción adicional</label>
                    <textarea
                        value={formData.descripcion}
                        onChange={(e) => setFormData({ ...formData, descripcion: e.target.value })}
                        placeholder="Detalles adicionales del gasto..."
                        rows="3"
                    />
                </div>

                <div className="form-grupo checkbox">
                    <label>
                        <input
                            type="checkbox"
                            checked={formData.esCompartido}
                            onChange={(e) => setFormData({ ...formData, esCompartido: e.target.checked })}
                        />
                        Gasto compartido entre inquilinos
                    </label>
                </div>

                <button type="submit" className="btn-primario">
                    💾 Registrar Gasto
                </button>
            </form>
        </div>
    );
}

export default GastosForm;
